# -*- coding: utf-8 -*-
# patch_iskra_live.py
# ============================================================
# ПАТЧ: первое звено Совета — живая Искра (A01).
# Спринт 45 · 2026-06-16
#
#   1. studio/modules/trading/iskra_live.py  — НОВЫЙ мозг прогона:
#      MT5 -> ядро -> модель -> {narrative, signal}, history_dna, стата.
#   2. studio/economy/ui_exchange.py  — кнопка "РЫНОК" (поднимает контур
#      и будит Искру), аватар поднят наверх, панель ПРИБОРЫ под аватаром.
#   3. main.py  — насос БОЛЬШЕ НЕ стартует при запуске студии.
#      MT5 поднимается по кнопке РЫНОК. Мультик делаешь — терминал спит.
#
# Бэкап (.bak). Запуск из корня репо:  python patch_iskra_live.py
# ============================================================
import base64, os, shutil

FILES = {
    "studio/modules/trading/iskra_live.py": "",
    "studio/economy/ui_exchange.py": "",
    "main.py": ""
}

def main():
    root = os.getcwd()
    print("=" * 60)
    print("  ПАТЧ: ЖИВАЯ ИСКРА (A01) — первое звено Совета")
    print("=" * 60)
    for dest, b64 in FILES.items():
        path = os.path.join(root, dest.replace("/", os.sep))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            shutil.copy2(path, path + ".bak")
            print(f"  [BAK] {dest} -> {dest}.bak")
        open(path, "wb").write(base64.b64decode(b64))
        print(f"  [OK ] {dest}")
    print("=" * 60)
    print("  ГОТОВО.")
    print("")
    print("  Теперь студия стартует БЕЗ MT5 (можно делать мультики).")
    print("  Чтобы оживить Искру:")
    print("   1. Открой терминал MetaTrader 5, войди на ДЕМО-счёт,")
    print("      убедись что символ XAUUSD виден в Market Watch.")
    print("   2. Запусти студию, открой /dashboard -> кнопка 'Биржа'.")
    print("   3. На Бирже нажми '📡 РЫНОК'.")
    print("      Искра возьмёт свежий бар H4, подумает живой моделью,")
    print("      голос -> в отчёт (правый экран), цифры -> под аватар.")
    print("")
    print("  Если терминал закрыт — Искра честно скажет об этом в чат.")
    print("=" * 60)

if __name__ == "__main__":
    main()
